using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
class Verify {static int Main(string[] a){try{var asm=Assembly.LoadFile(Path.GetFullPath(a[0]));var json=new JavaScriptSerializer();var expected=json.Deserialize<Dictionary<string,string>>(File.ReadAllText(a[1]));var actual=new Dictionary<string,string>();using(var hash=SHA256.Create())foreach(var name in asm.GetManifestResourceNames()){using(var s=asm.GetManifestResourceStream(name))actual.Add(name,BitConverter.ToString(hash.ComputeHash(s)).Replace("-","").ToLowerInvariant());}if(actual.Count!=expected.Count||expected.Any(r=>!actual.ContainsKey(r.Key)||actual[r.Key]!=r.Value))throw new Exception("Embedded resources differ");var f=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static;int version=(int)asm.GetType("ElsFriends.AutoUpdate").GetField("Version",f).GetRawConstantValue();if(version!=int.Parse(a[3]))throw new Exception("Wrong version");var c=asm.GetType("ElsFriends.ComponentRuntime");var def=c.GetMethod("Definition",f).Invoke(null,null);string archive=(string)def.GetType().GetField("Hash").GetValue(def);if(archive!=a[4])throw new Exception("Wrong runtime identity");var cohort=asm.GetType("ElsFriends.UIScrollRuntimeCohort");if((string)cohort.GetField("FriendsProfileHash",f).GetRawConstantValue()!=a[5])throw new Exception("Wrong profile pin");if((int)cohort.GetField("FriendsCount",f).GetRawConstantValue()!=((System.Collections.ICollection)def.GetType().GetField("Files").GetValue(def)).Count)throw new Exception("Wrong component count");File.WriteAllText(a[2],json.Serialize(new{ok=true,version=version,resources=actual.Count,signed_default_payload=archive,profile_pin=a[5],game_started=false}));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
